import{_ as e,o as i,c as r,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Mecánica","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/tinkering.md","filePath":"es/guide/professions/tinkering.md"}'),s={name:"es/guide/professions/tinkering.md"};function t(o,a,d,c,l,p){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="tinkering" tabindex="-1">Mecánica <a class="header-anchor" href="#tinkering" aria-label="Enlace permanente a &quot;Mecánica&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Comprende y construye mecanismos de precisión con límites claros.</li><li>El diagnóstico, la reparación, las trampas y la seguridad crean funciones en expediciones.</li><li>La automatización y los autómatas son posibilidades futuras, no fábricas ilimitadas.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="future-directions-and-limits"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Trabajar en un dispositivo</td><td>Inspecciona, diseña, monta, calibra, prueba y mantén.</td></tr><tr><td>Aprender del mundo</td><td>Registra indicios en un diario mecánico; la ingeniería inversa puede dañar el dispositivo.</td></tr><tr><td>Apoyar al grupo</td><td>Diagnostica trampas, repara maquinaria o ayuda a restaurar un elevador o un puente.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Los artesanos de Tinkering ya fabrican herramientas, componentes y dispositivos útiles.</td><td>El diagnóstico, la calibración y la ingeniería inversa se convierten en actividades más profundas.</td></tr><tr><td>UO posterior también incluye mascotas mecánicas.</td><td>Los futuros autómatas encajarían en un sistema de mecanismos más amplio y limitado; los detalles siguen abiertos.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/tinkering/" target="_blank" rel="noreferrer">Tinkering</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un mecánico podría diagnosticar un elevador averiado durante una expedición. Comprender el mecanismo puede revelar cómo repararlo, en lugar de tratar cada dispositivo como una receta.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Mecánica comprende y construye cerraduras; Lockpicking las abre. La seguridad y el robo necesitan contramedidas, sin permitir perder toda una casa con facilidad.</li><li>Las cargas alquímicas, las puertas, las alarmas y los comederos son posibilidades. Los límites de automatización y los gólems avanzados siguen sin decidirse.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alquimia</a> · <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Herrería</a> · <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpintería</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Práctica de Familiarity</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Mecánica</a></p>',18)])])}const h=e(s,[["render",t]]);export{m as __pageData,h as default};
